
.pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 20px;
  height: 44px;
  border-top: 1px solid var(--border);
}
.pagination-left {
  display: flex;
  align-items: center;
  gap: 8px;
}
.pagination-right {
  display: flex;
  align-items: center;
  gap: 4px;
}
.pagination-horizontal {
  display: flex;
  align-items: center;
}
.pagination-desc {
  color: var(--muted-foreground);
  font-size: 14px;
  line-height: 20px;
}
.pagination-list {
  display: flex;
  align-items: center;
}
.pagination-list a {
  width: 24px;
  height: 20px;
  color: var(--muted-foreground);
  font-family: "InterTight", sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 20px;
  text-decoration: none;
}
.pagination-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  color: var(--foreground);
  transition: all 0.2s linear;
}
.pagination-box:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.pagination-disable {
  user-select: none;
  cursor: not-allowed;
  color: var(--muted-foreground);
  opacity: 0.5;
}
.pagination-disable:hover {
  background: none !important;
}
